import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2020Q1 Ceph社区季度进展报告","date":"2020-03-01T00:00:00.000Z","updated":"2020-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020Q1_Ceph社区季度总结.md","filePath":"posts/2020/2020Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020Q1_Ceph社区季度总结.md"};function h(l,e,_,s,n,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ceph-社区-2020q1-季度进展报告" tabindex="-1">Ceph 社区 2020Q1 季度进展报告 <a class="header-anchor" href="#ceph-社区-2020q1-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2020Q1 季度进展报告&quot;">​</a></h1><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区围绕以下几个核心方向持续深入讨论：</p><p><strong>Crimson/SeaStar OSD 新架构</strong> Crimson 项目是本季度最活跃的研发方向之一。<a href="/VideoSummary/posts/2020/2020-01-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2020-01-07 会议</a>)和<a href="/VideoSummary/posts/2020/2020-01-14_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2020-01-14 会议</a>)持续推进 B+树异步实现、事务处理机制、以及如何减少写放大问题。团队在 SeaStar 网络栈集成、内存零拷贝优化等方面投入了大量精力。</p><p><strong>Orchestrator 与部署自动化</strong> Orchestrator 相关会议贯穿整个季度（<a href="./2020-01-08_-_Ceph_Orchestration_Meeting.html">1月8日</a>、<a href="/VideoSummary/posts/2020/2020-01-13_-_-_Ceph_Orchestration_Meeting.html">1月13日</a>)、<a href="/VideoSummary/posts/2020/2020-01-20_-_-_Ceph_Orchestration_Meeting.html">1月20日</a>)、<a href="/VideoSummary/posts/2020/2020-01-27_-_-_Ceph_Orchestration_Meeting.html">1月27日</a>)），重点讨论 OSD 生命周期管理（移除、替换、排空）、cephadm 与 Rook 的协作边界，以及 Python 客户端库的独立化。</p><p><strong>PG 自动缩放与性能调优</strong><a href="/VideoSummary/posts/2020/2020-01-16_-_-_Ceph_Performance_Meeting.html">1月16日</a>)、<a href="/VideoSummary/posts/2020/2020-01-23_-_-_Ceph_Performance_Meeting.html">1月23日</a>)、<a href="./2020-01-30_-_Ceph_Performance_Meeting.html">1月30日</a>的性能会议持续关注 PG autoscaler 的默认参数调整、BlueStore 空间放大问题，以及 buffer list 优化。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="crimson-seastar-osd" tabindex="-1">Crimson/SeaStar OSD <a class="header-anchor" href="#crimson-seastar-osd" aria-label="Permalink to &quot;Crimson/SeaStar OSD&quot;">​</a></h3><ul><li>正在从零开始实现 B+树，高度定制化以适配 Ceph 的事务语义，不依赖外部库。需要同时支持物理地址和逻辑地址两个版本，以应对不同存储后端。</li><li>探索混合逻辑时钟（HLC）实现轻量级快照的可行性。</li><li>讨论了 TCP/IP 栈中套接字在多核环境下的放置优化策略，目标是实现真正的零拷贝 I/O。</li><li>详见 <a href="/VideoSummary/posts/2020/2020-01-14_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2020-01-14Crimson 会议</a>)。</li></ul><h3 id="bluestore-性能优化" tabindex="-1">BlueStore 性能优化 <a class="header-anchor" href="#bluestore-性能优化" aria-label="Permalink to &quot;BlueStore 性能优化&quot;">​</a></h3><ul><li>针对 blob 空间放大问题，讨论了将最小分配大小从 64k 调整为 4k 的方案，但需权衡 HDD 场景下的性能回退风险。Octopus 版本计划若无法及时解决分配器问题，HDD 将回退到 64k。</li><li>Igor 提交了通过改变数据结构减少缓存 PG 内存占用的 PR，以及简化 pin/unpin 逻辑的 PR（解决了之前修复引入的竞态条件）。</li><li>详见 <a href="/VideoSummary/posts/2020/2020-01-23_-_-_Ceph_Performance_Meeting.html">1月23日性能会议</a>)。</li></ul><h3 id="pg-autoscaler" tabindex="-1">PG Autoscaler <a class="header-anchor" href="#pg-autoscaler" aria-label="Permalink to &quot;PG Autoscaler&quot;">​</a></h3><ul><li>将默认 PG 数量从原有值提升至 32 的PR 已合并，目标是改善初始数据分布和 OSD 响应性。</li><li>在 OpenShift 环境中测试发现数据分布不均问题，通过调整目标比率并启用 PG balancer 得到改善。</li><li>讨论了根据 PG 数量自动选择 PG log 长度以优化内存使用。</li><li>详见 <a href="./2020-01-16_-_Ceph_Performance_Meeting.html">1月16日</a>和<a href="/VideoSummary/posts/2020/2020-01-30_-_-_Ceph_Performance_Meeting.html">1月30日性能会议</a>)。</li></ul><h3 id="orchestrator-cephadm" tabindex="-1">Orchestrator / cephadm <a class="header-anchor" href="#orchestrator-cephadm" aria-label="Permalink to &quot;Orchestrator / cephadm&quot;">​</a></h3><ul><li>提出新的 OSD 排空管理模块，可被 Rook 和 cephadm 直接消费，也可供 Dashboard 独立调用。排空流程包括设置权重为零、等待 OSD 清空等步骤，并引入 safe command API。</li><li>Ceph Python 客户端库决定独立为单独仓库（置于 Rook 组织下），通过 pip 安装，并使用 GitHub Actions 保持与 CRD 变更同步。</li><li>停用旧的 trailer bots，统一迁移到新 Orchestrator 项目。</li><li>详见 <a href="/VideoSummary/posts/2020/2020-01-13_-_-_Ceph_Orchestration_Meeting.html">1月13日</a>)和<a href="./2020-01-27_-_Ceph_Orchestration_Meeting.html">1月27日 Orchestrator 会议</a>。</li></ul><h3 id="rgw" tabindex="-1">RGW <a class="header-anchor" href="#rgw" aria-label="Permalink to &quot;RGW&quot;">​</a></h3><ul><li>Erica 添加的 RGW 过滤逻辑通过 QA 测试，但需进一步调整。</li><li>讨论了允许 zone 配置 index charts（增加 bucket shards 数量）的 PR。</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><ul><li><strong>Rook 1.2 发布</strong>：<a href="/VideoSummary/posts/2020/2020-01-08_-_-_Ceph_Orchestration_Meeting.html">1月8日 Orchestrator 会议</a>)提到 Rook 1.2 已发布，并计划进行第一次补丁发布。安全审查发现的敏感信息日志记录问题已有 PR 处理。</li><li><strong>Luminous 版本维护决策</strong>：<a href="/VideoSummary/posts/2020/2020-01-21_-_-_Ceph_Testing_Meeting.html">测试会议</a>)讨论了 Luminous 版本的维护状态，决定尽快完成其测试和发布，并讨论了是否继续长期支持的问题。</li><li><strong>Nautilus CVE 热修复</strong>：即将发布两个 CVE 的安全更新，热修复流程已明确。</li><li><strong>取消每日 Orchestrator 站立会议</strong>：改为每周一次，减少会议开销。</li><li><strong>Pacific 版本方向确定</strong>：<a href="/VideoSummary/posts/2020/CDS_Pacific_-_Orchestrator_cephadm_rook.html">CDS Pacific Orchestrator 会议</a>)明确 Pacific 将以修复 Octopus 遗留问题为主，而非增加新功能，重点包括 OSD 管理、升级流程和开发者体验改善。</li></ul><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><h3 id="科学用户组" tabindex="-1">科学用户组 <a class="header-anchor" href="#科学用户组" aria-label="Permalink to &quot;科学用户组&quot;">​</a></h3><p><a href="/VideoSummary/posts/2020/2020-01-22_-_-_Ceph_Science_User_Group_Meeting.html">1月22日科学用户组会议</a>)汇聚了多个大型科学计算用户：</p><ul><li>Liam Monahan 分享了 3.5PB 集群在机器学习场景的运维经验。</li><li>Tom Bennett 介绍了南非 MeerKAT 射电望远镜的 Ceph 存储方案（数亿个对象），详细内容见 <a href="/VideoSummary/posts/2020/2020-Jan-23_-_-_Ceph_Tech_Talk_-_Ceph_for_Storing_MeerKAT_Radio_Telescope_Data.html">Tech Talk 专题演讲</a>)。MeerKAT 自 2018 年起使用 Ceph 生产集群，当前运行 Luminous，计划升级至 Nautilus，并测试 EC 池。</li><li>下次科学用户组会议计划三月举行，时间将参考 Cephalocon 安排。</li></ul><h3 id="文档工作" tabindex="-1">文档工作 <a class="header-anchor" href="#文档工作" aria-label="Permalink to &quot;文档工作&quot;">​</a></h3><p><a href="/VideoSummary/posts/2020/2020-01-08_-_-_Ceph_DocUBetter_Meeting.html">DocUBetter 会议</a>)和<a href="/VideoSummary/posts/2020/2020-01-22_-_-_Ceph_DocUBetter_Meeting.html">1月22日文档会议</a>)持续推进：</p><ul><li>完成 Ceph 入门指南 PR。</li><li>完善 PG 不一致性修复文档，补充 &quot;stat mismatch&quot; 场景的处理步骤。</li><li>计划建立文档请求热线，并研究自动分配文档相关 bug 的机制。</li><li>计划与 Brad合作编写 RADOS 速查表。</li></ul><h3 id="测试基础设施" tabindex="-1">测试基础设施 <a class="header-anchor" href="#测试基础设施" aria-label="Permalink to &quot;测试基础设施&quot;">​</a></h3><p><a href="/VideoSummary/posts/2020/2020-01-21_-_-_Ceph_Testing_Meeting.html">测试会议</a>)讨论了：</p><ul><li>CentOS 7 → CentOS 8 测试环境迁移进展及遇到的失败问题。</li><li>openSUSE 15.1 在 Sepia 测试环境中的支持推进。</li><li>Jenkins 发布流程改进，包括分支和发布管理的优化。</li></ul><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论，预计 2020Q 将重点推进以下方向：</p><ol><li><p><strong>Crimson OSD 持续演进</strong>：B+树异步实现将进入更完整的测试阶段，恢复机制（日志处理、回填）的实现将是重点，参见 <a href="/VideoSummary/posts/2020/2020-10-21_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">10月 Crimson 会议</a>)中对恢复机制的前瞻讨论。</p></li><li><p><strong>Octopus 版本发布准备</strong>：BlueStore 最小分配大小的最终决策、PG autoscaler 的进一步稳定化，以及 Nautilus CVE 热修复的跟进。</p></li><li><p><strong>cephadm 成熟化</strong>：OSD 排空/替换 API 的完整实现，Python 客户端库独立仓库的建立和 CI 集成，以及 cephadm 在 Pacific 中作为主要部署工具的地位确立。</p></li><li><p><strong>Cephalocon 2020</strong>：社区活动将为各子项目提供集中讨论和路线图对齐的机会，科学用户组计划在此期间组织 Birds of a Feather 会议。</p></li><li><p><strong>测试环境现代化</strong>：完成 CentOS 8 迁移，推进 openSUSE 15.1 支持，持续改进 CI 基础设施。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2020/2020-01-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2020-01-07 :: Crimson SeaStor OSD Weekly Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-08_-_-_Ceph_DocUBetter_Meeting.html">2020-01-08:: Ceph DocUBetter Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-08_-_-_Ceph_Orchestration_Meeting.html">2020-01-08 :: Ceph Orchestration Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-13_-_-_Ceph_Orchestration_Meeting.html">2020-01-13 -- Ceph Orchestration Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-14_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2020-01-14 :: Crimson SeaStor OSD Weekly Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-16_-_-_Ceph_Performance_Meeting.html">2020-01-16 -- Ceph Performance Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-20_-_-_Ceph_Orchestration_Meeting.html">2020-01-20 :: Ceph Orchestration Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-21_-_-_Ceph_Testing_Meeting.html">2020-01-21 :: Ceph Testing Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-22_-_-_Ceph_DocUBetter_Meeting.html">2020-01-22:: Ceph DocUBetter Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-22_-_-_Ceph_Science_User_Group_Meeting.html">2020-01-22 :: Ceph Science User Group Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-23_-_-_Ceph_Performance_Meeting.html">2020-01-23 -- Ceph Performance Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-27_-_-_Ceph_Orchestration_Meeting.html">2020-01-27 :: Ceph Orchestration Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-01-30_-_-_Ceph_Performance_Meeting.html">2020-01-30 -- Ceph Performance Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-10-21_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2020-10-21 :: Crimson SeaStor OSD Weekly Meeting</a>)</li><li><a href="/VideoSummary/posts/2020/2020-Jan-23_-_-_Ceph_Tech_Talk_-_Ceph_for_Storing_MeerKAT_Radio_Telescope_Data.html">2020-Jan-23 :: Ceph Tech Talk - Ceph for Storing MeerKAT Radio Telescope Data</a>)</li><li><a href="/VideoSummary/posts/2020/CDS_Pacific_-_Orchestrator_cephadm_rook.html">CDS Pacific: Orchestrator, cephadm, rook</a>)</li></ul>',39)])])}const u=a(o,[["render",h]]);export{c as __pageData,u as default};
